import * as T from 'three';
import { RGBELoader } from 'three/addons/loaders/RGBELoader.js';
// Poly Haven Studio Small 08, Sergej Majboroda, CC0. Linear-light downsample to 256×128.
const data='';
export function studioEnvironment(renderer){const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));const hdr=new RGBELoader().parse(bytes.buffer);const texture=new T.DataTexture(hdr.data,hdr.width,hdr.height,T.RGBAFormat,hdr.type);texture.mapping=T.EquirectangularReflectionMapping;texture.colorSpace=T.LinearSRGBColorSpace;texture.minFilter=texture.magFilter=T.LinearFilter;texture.flipY=true;texture.needsUpdate=true;const pmrem=new T.PMREMGenerator(renderer);const target=pmrem.fromEquirectangular(texture);texture.dispose();pmrem.dispose();return target.texture;}
